// 校验输入数据是否包含主角未知的敏感信息
for (const item of $input.all()) {
    if (item.json.visible_info && item.json.visible_info.includes("敏感/未知内容")) {
        throw new Error("校验失败：可见信息中包含了主角未知的内容！");
    }
}
return $input.all();

// 修复 LLM 返回的 JSON 格式
for (const item of $input.all()) {
    let text = item.json.output || item.json.text || "";
    try {
        const jsonMatch = text.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
            item.json.repaired_json = JSON.parse(jsonMatch[0]);
        } else {
            item.json.repaired_json = JSON.parse(text);
        }
    } catch (e) {
        item.json.repaired_json = { error: "JSON无法解析", original: text };
    }
}
return $input.all();

// 返回主角行动候选结果
return $input.all().map(item => {
    return {
        json: {
            action_candidates: item.json.repaired_json || item.json
        }
    };
});
